export interface SpringEntityOptions extends LineOptions {
    /** Number of full coil oscillations (Default: 8) */
    coils?: number;

    /** Amplitude / half-width of the coil in world units (Default: 0.35) */
    radius?: number;

    /** Length of straight lead-in and lead-out segments at the ends (Default: 0.4) */
    leadLength?: number;

    /** Visual style: 'coil' (zigzag), 'helix' (smooth sine), or 'line' (straight rod) */
    style?: SpringStyle;

    /** Number of sampling subdivisions per turn when using 'helix' style (Default: 8) */
    segmentsPerCoil?: number;

    /** Source entity to bind to */
    entityA?: Entity;

    /** Target entity to bind to */
    entityB?: Entity;

    /** Local anchor offset on entityA */
    localAnchorA?: Vec2Type;

    /** Local anchor offset on entityB */
    localAnchorB?: Vec2Type;

    /** Scene instance to automatically attach real-time update loop to */
    scene?: Scene;
}

import { Scene, Circle, Spring, Color, Vec3, Rate } from "retiam";

const scene = new Scene({ canvas });

// 1. Fixed ceiling anchor
const ceiling = new Circle(0.3, {
    position: [0, 4, 0],
    fill: Color.fromHex("#64748b")
});
scene.add(ceiling);

// 2. Oscillating mass bob
const bob = new Circle(0.8, {
    position: [0, -2, 0],
    fill: Color.fromHex("#f59e0b")
});
scene.add(bob);

// 3. Dynamic physics spring binding ceiling and bob
const spring = new Spring({
    entityA: ceiling,
    entityB: bob,
    coils: 10,
    radius: 0.4,
    style: "coil",
    stroke: Color.WHITE,
    stroke_width: 0.08,
    scene: scene // Automatically registers frame update listener
});
scene.add(spring);

// 4. Animate harmonic oscillation
scene.always(({ time }) => {
    bob.transform.position.y = -2.0 + Math.sin(time * 4.0) * 1.5;
});
